package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithPools {

    private static final BigDecimal HUNDRED = new BigDecimal("100.00");

    // A member with a retirement date set, whatever the date, counts 0.00 toward the pool's total.
    // Each member of a balanced pool cuts the pool's pot times their share / 100, half to even to two decimals (a retired
    // member 0.00); the remainder goes to the member with the largest share, the earliest added on a tie, so the cuts
    // total the pot. A pool that is a member of none has the sheet's pot; a pool that is a member of another has its cut
    // there as its pot (none when the pool above has no cuts).
    public void respond(@PathVariable("sheetId") String sheetId, Pools pools, People people, Settings settings,
            ObjectResponse<List<PoolResponse>> response) {
        String sheet = sheetId.trim();
        Map<Long, Person> byId = people.list(sheet).stream().collect(Collectors.toMap(Person::id, Function.identity()));
        List<Pools.Membership> members = pools.members(sheet);
        Map<String, String> parents = pools.parents(sheet);
        BigDecimal sheetPot = settings.pot(sheet);
        List<String> names = pools.names(sheet);

        Map<String, List<Pools.Membership>> inByPool = new HashMap<>();
        Map<String, BigDecimal> totals = new HashMap<>();
        for (String name : names) {
            List<Pools.Membership> in = new ArrayList<>();
            BigDecimal total = BigDecimal.ZERO.setScale(2);
            for (Pools.Membership m : members) {
                if (!m.pool().equals(name)) {
                    continue;
                }
                if (m.memberPool() == null) {
                    Person person = byId.get(m.personId());
                    if (person == null) {
                        continue;
                    }
                    if (person.retiredFrom() == null) {
                        total = total.add(m.share());
                    }
                } else {
                    total = total.add(m.share());
                }
                in.add(m);
            }
            inByPool.put(name, in);
            totals.put(name, total);
        }

        // Each pool's cuts, figured from the top of its chain down (null when it has none).
        Map<String, List<BigDecimal>> cutsByPool = new HashMap<>();
        for (String name : names) {
            cutsOf(name, sheetPot, parents, inByPool, totals, byId, cutsByPool);
        }

        List<PoolResponse> out = new ArrayList<>();
        for (String name : names) {
            List<Pools.Membership> in = inByPool.get(name);
            List<BigDecimal> cuts = cutsByPool.get(name);
            List<PoolResponse.Member> shown = new ArrayList<>();
            for (int i = 0; i < in.size(); i++) {
                Pools.Membership m = in.get(i);
                String cut = cuts == null ? "" : cuts.get(i).toPlainString();
                if (m.memberPool() != null) {
                    shown.add(new PoolResponse.Member(0, m.memberPool(), m.share().toPlainString(), false, cut,
                            m.memberPool()));
                } else {
                    Person person = byId.get(m.personId());
                    shown.add(new PoolResponse.Member(person.id(), person.name(), m.share().toPlainString(),
                            person.retiredFrom() != null, cut, null));
                }
            }
            BigDecimal total = totals.get(name);
            out.add(new PoolResponse(name, shown, total.toPlainString(), total.compareTo(HUNDRED) == 0));
        }
        response.send(out);
    }

    private static List<BigDecimal> cutsOf(String name, BigDecimal sheetPot, Map<String, String> parents,
            Map<String, List<Pools.Membership>> inByPool, Map<String, BigDecimal> totals, Map<Long, Person> byId,
            Map<String, List<BigDecimal>> cutsByPool) {
        if (cutsByPool.containsKey(name)) {
            return cutsByPool.get(name);
        }
        BigDecimal pot = sheetPot;
        String parent = parents.get(name);
        if (parent != null) {
            pot = null;
            List<BigDecimal> above = cutsOf(parent, sheetPot, parents, inByPool, totals, byId, cutsByPool);
            if (above != null) {
                List<Pools.Membership> in = inByPool.get(parent);
                for (int i = 0; i < in.size(); i++) {
                    if (name.equals(in.get(i).memberPool())) {
                        pot = above.get(i);
                    }
                }
            }
        }
        boolean balanced = totals.get(name).compareTo(HUNDRED) == 0;
        List<BigDecimal> cuts = balanced && pot != null ? cuts(pot, inByPool.get(name), byId) : null;
        cutsByPool.put(name, cuts);
        return cuts;
    }

    private static boolean retired(Pools.Membership m, Map<Long, Person> byId) {
        return m.memberPool() == null && byId.get(m.personId()).retiredFrom() != null;
    }

    private static List<BigDecimal> cuts(BigDecimal pot, List<Pools.Membership> in, Map<Long, Person> byId) {
        List<BigDecimal> cuts = new ArrayList<>();
        BigDecimal sum = BigDecimal.ZERO.setScale(2);
        int largest = -1;
        for (int i = 0; i < in.size(); i++) {
            Pools.Membership m = in.get(i);
            boolean retired = retired(m, byId);
            BigDecimal cut = retired ? BigDecimal.ZERO.setScale(2)
                    : pot.multiply(m.share()).divide(HUNDRED, 2, RoundingMode.HALF_EVEN);
            cuts.add(cut);
            sum = sum.add(cut);
            if (!retired && (largest < 0 || m.share().compareTo(in.get(largest).share()) > 0)) {
                largest = i;
            }
        }
        if (largest >= 0) {
            cuts.set(largest, cuts.get(largest).add(pot.subtract(sum)));
        }
        return cuts;
    }
}
package net.officefloor.hq.app.pool;

import java.util.List;

/**
 * A pool as the screen sees it: its name, its members, the total of their shares (a retired member's counting 0.00)
 * with two decimals, and whether that total is exactly 100.00.
 */
public record PoolResponse(String name, List<Member> members, String totalShare, boolean balanced) {

    /**
     * A member: the person's id and name, their share with two decimals, whether they are retired, and their cut of the
     * pot with two decimals ("" when the pool is not balanced or there is no pot). A member that is another pool has
     * personId 0, its name as name and as pool, and is never retired; pool is null for a person.
     */
    public record Member(long personId, String name, String share, boolean retired, String cut, String pool) {
    }
}
# GET /api/sheets/{sheetId}/pools — the sheet's pools, in the order added, each with its members (in the order added),
# its total share (a retired member's share counting 0.00) and whether it is balanced (the total is exactly 100.00),
# and each member's cut of the sheet's pot when the pool is balanced and there is a pot.
respond:
  class: net.officefloor.hq.app.pool.RespondWithPools
  govern: [ readonly-transaction ]
import { useQuery } from '@tanstack/react-query';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { peopleQuery } from '../people/peopleQuery';
import { sumDue } from '../rates/ratesQuery';
import { poolsQuery } from './poolsQuery';
import type { Pool } from './poolsQuery';

/** A person's cut total: their cut in every pool they are a member of, added up; a pool that shows no cut adds nothing. */
function cutTotal(pools: Pool[], personId: number): string {
  const cuts = pools.flatMap((p) => p.members.filter((m) => m.pool === null && m.personId === personId && m.cut !== '').map((m) => m.cut));
  return sumDue(cuts);
}

function PersonCutTotal({ sheetId, personId }: { sheetId: string; personId: number }) {
  const pools = useQuery(poolsQuery(sheetId)).data ?? [];
  return <td data-testid="person-cut-total">{cutTotal(pools, personId)}</td>;
}

/** The sheet's cut total: everyone's cut total added up. */
function CutTotal({ sheetId }: { sheetId: string }) {
  const pools = useQuery(poolsQuery(sheetId)).data ?? [];
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  return (
    <p data-testid="rollup-cut">
      Cut total <strong data-testid="rollup-cut-total">{sumDue(people.map((p) => cutTotal(pools, p.id)))}</strong>
    </p>
  );
}

export const contributions = [
  PersonHeaders.fill({ order: 22.5, Component: () => <th>Cuts</th> }),
  PersonCells.fill({ order: 22.5, Component: PersonCutTotal }),
  SheetPanel.fill({ order: 25.6, Component: CutTotal }),
];
import { getJson } from '../../api/http';
import { peopleKey } from '../people/peopleQuery';

/** A member of a pool: the person's id and name, their share percent with two decimals, whether they are retired, and their
